// Signs the GET request. GET has no body, so the empty string is what is signed.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret) throw new Error('LENDLOOP_SHARED_SECRET is not set on the n8n container');

const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');

return [{ json: { timestamp, signature } }];

// Turns the response into one item per loan, each with its own signature and
// idempotency key. No notification is sent here: the reminder is *claimed* first
// so that a re-run of this workflow cannot send a second reminder.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;

const response = $input.first().json;
const loans = Array.isArray(response.loans) ? response.loans : [];
const today = new Date().toISOString().slice(0, 10);

const output = [];

for (const loan of loans) {
  if (!loan.loanId || !loan.daysOverdue || loan.daysOverdue <= 0) continue;

  const dueDate = new Date(loan.dueDate).toISOString().slice(0, 10);
  const message = `Your loan of ${loan.toolName} was due ${dueDate} and is ${loan.daysOverdue} day(s) late. Please return it to your neighbor.`;

  const body = JSON.stringify({
    loanId: loan.loanId,
    channel: 'mock',
    detail: `Overdue reminder for ${loan.toolName} (${loan.daysOverdue}d late)`,
  });

  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');

  output.push({
    json: {
      loanId: loan.loanId,
      body,
      timestamp,
      signature,
      recipientEmail: loan.borrowerEmail ?? 'unknown',
      // Derived from data, so a retried run and a duplicate schedule run produce
      // the same key and the claim collapses to one record.
      idempotencyKey: `reminder:${loan.loanId}:${loan.dueDate}:${today}`,
      message,
    },
  });
}

return output;

// Sends only for reminders this run actually claimed. A duplicate claim means a
// previous run already notified this borrower, so re-running the schedule is
// safe: the record and the send collapse together.
const source = $('Build signed reminders').all();

const results = $input.all().map((item, index) => {
  const claim = item.json ?? {};
  const original = source[index]?.json ?? {};

  if (claim.ok !== true || claim.duplicate !== false) return null;

  console.log(
    `[LENDLOOP MOCK] to=${original.recipientEmail ?? 'unknown'} subject=Overdue: ${original.message}`,
  );

  return { json: { loanId: original.loanId, sent: true } };
});

return results.filter(Boolean);
